function noCancel<A extends unknown[]>(fn: (...args: A) => void, ms: number) {
  return (...args: A) => { setTimeout(() => fn(...args), ms); };
}
function leadingEdge<A extends unknown[]>(fn: (...args: A) => void, ms: number) {
  let timer: ReturnType<typeof setTimeout> | undefined;
  return (...args: A) => {
    if (timer === undefined) fn(...args);
    clearTimeout(timer);
    timer = setTimeout(() => { timer = undefined; }, ms);
  };
}
function firstValue<A extends unknown[]>(fn: (...args: A) => void, ms: number) {
  let timer: ReturnType<typeof setTimeout> | undefined;
  let first: A | undefined;
  return (...args: A) => {
    clearTimeout(timer);
    first ??= args;
    timer = setTimeout(() => { const a = first!; first = undefined; fn(...a); }, ms);
  };
}
function fromFirstKeystroke<A extends unknown[]>(fn: (...args: A) => void, ms: number) {
  let timer: ReturnType<typeof setTimeout> | undefined;
  let latest: A;
  return (...args: A) => {
    latest = args;
    timer ??= setTimeout(() => { timer = undefined; fn(...latest); }, ms);
  };
}
function tooEarly<A extends unknown[]>(fn: (...args: A) => void, ms: number) {
  return debounce(fn, ms - 100);
}
function onlyOnce<A extends unknown[]>(fn: (...args: A) => void, ms: number) {
  let fired = false;
  return debounce((...args: A) => { if (!fired) { fired = true; fn(...args); } }, ms);
